/** @type {import('jest').Config} */
module.exports = {
  preset: 'ts-jest',
  testEnvironment: 'node',
  roots: ['<rootDir>/__tests__'],
  testMatch: ['**/*.test.ts'],
  clearMocks: true,
};

export interface Page {
  slug: string;
  title: string;
  date?: string;
  tags?: string[];
  contentHtml: string;
  content: string;
}

export interface ParsedMarkdown {
  data: Record<string, unknown>;
  content: string;
}

import matter from 'gray-matter';
import type { ParsedMarkdown } from './types';

const DELIMITER = '---';
const BOM = '\uFEFF';

function stripBom(text: string): string {
  return text.startsWith(BOM) ? text.slice(1) : text;
}

function isDelimiter(line: string): boolean {
  return line.trim() === DELIMITER;
}

/**
 * Extract the raw `---`-delimited YAML block from a markdown string.
 * Returns null when no frontmatter block is present.
 */
function extractYamlBlock(markdown: string): string | null {
  const lines = stripBom(markdown).split(/\r?\n/);
  if (lines.length === 0 || lines[0].trim() !== DELIMITER) {
    return null;
  }
  for (let i = 1; i < lines.length; i++) {
    if (isDelimiter(lines[i])) {
      return lines.slice(1, i).join('\n');
    }
  }
  return null;
}

/**
 * Remove the `---`-delimited frontmatter block, mirroring gray-matter's
 * behaviour of keeping the blank line that follows the closing delimiter.
 */
function stripFrontmatter(markdown: string): string {
  const lines = stripBom(markdown).split(/\r?\n/);
  if (lines[0].trim() !== DELIMITER) {
    return markdown;
  }
  for (let i = 1; i < lines.length; i++) {
    if (isDelimiter(lines[i])) {
      return lines.slice(i + 1).join('\n');
    }
  }
  return markdown;
}

function parseYamlList(value: string): string[] {
  const inner = value.slice(1, -1);
  if (inner.trim() === '') {
    return [];
  }
  return inner
    .split(',')
    .map((item) => item.trim())
    .filter((item) => item.length > 0)
    .map((item) => {
      if (
        (item.startsWith('"') && item.endsWith('"')) ||
        (item.startsWith("'") && item.endsWith("'"))
      ) {
        return item.slice(1, -1);
      }
      return item;
    });
}

/**
 * A deliberately simple `key: value` splitter for YAML frontmatter.
 * Supports quoted strings, booleans, numbers and inline flow-style lists.
 * Anything more exotic is left untouched (the raw string is used).
 */
export function parseYamlBlock(text: string): Record<string, unknown> {
  const result: Record<string, unknown> = {};
  for (const rawLine of text.split(/\r?\n/)) {
    const line = rawLine.trim();
    if (line.length === 0 || line.startsWith('#')) {
      continue;
    }
    const colonIndex = line.indexOf(':');
    if (colonIndex <= 0) {
      continue;
    }
    const key = line.slice(0, colonIndex).trim();
    if (key.length === 0) {
      continue;
    }
    let value = line.slice(colonIndex + 1).trim();
    if (value.length === 0) {
      result[key] = '';
      continue;
    }
    if (
      (value.startsWith('"') && value.endsWith('"')) ||
      (value.startsWith("'") && value.endsWith("'"))
    ) {
      result[key] = value.slice(1, -1);
      continue;
    }
    if (value.startsWith('[') && value.endsWith(']')) {
      result[key] = parseYamlList(value);
      continue;
    }
    const lower = value.toLowerCase();
    if (lower === 'true') {
      result[key] = true;
      continue;
    }
    if (lower === 'false') {
      result[key] = false;
      continue;
    }
    if (/^-?\d+$/.test(value) || /^-?\d+\.\d+$/.test(value)) {
      result[key] = Number(value);
      continue;
    }
    result[key] = value;
  }
  return result;
}

/**
 * Parse the `---`-delimited frontmatter block with the simple YAML splitter.
 * JSON frontmatter (block starting with `{` or `[`) is delegated to gray-matter.
 */
function parseYamlFromMarkdown(markdown: string): Record<string, unknown> {
  const block = extractYamlBlock(markdown);
  if (block === null) {
    return {};
  }
  const trimmed = block.trim();
  if (trimmed.startsWith('{') || trimmed.startsWith('[')) {
    return {};
  }
  return parseYamlBlock(block);
}

/**
 * Parse markdown with frontmatter support.
 *
 * gray-matter handles stripping the frontmatter block and parsing JSON
 * frontmatter. YAML frontmatter is parsed by our own splitter and merged
 * on top of gray-matter's output, so YAML keys always win.
 */
export function parseFrontmatter(markdown: string): ParsedMarkdown {
  const normalized = stripBom(markdown);
  let grayMatterData: Record<string, unknown> = {};
  let content = normalized;
  try {
    const parsed = matter(normalized);
    grayMatterData = (parsed.data as Record<string, unknown>) ?? {};
    if (parsed.content !== undefined && parsed.content !== null) {
      content = parsed.content;
    }
  } catch {
    content = stripFrontmatter(normalized);
  }
  const yamlData = parseYamlFromMarkdown(normalized);
  const data: Record<string, unknown> = { ...grayMatterData, ...yamlData };
  return { data, content };
}

import { marked } from 'marked';
import { parseFrontmatter } from './frontmatter';
import type { ParsedMarkdown } from './types';

marked.setOptions({
  gfm: true,
  breaks: false,
});

/**
 * Render a markdown string to HTML and return the parsed frontmatter data.
 */
export function renderMarkdownToHtml(markdown: string): ParsedMarkdown & { html: string } {
  const { data, content } = parseFrontmatter(markdown);
  const html = marked.parse(content, { async: false }) as string;
  return { data, content, html };
}

import fs from 'fs';
import path from 'path';
import { renderMarkdownToHtml } from './markdown';
import type { Page } from './types';

export interface BuildOptions {
  contentDir: string;
  outputDir: string;
}

const MARKDOWN_EXTENSIONS = /\.(md|markdown)$/;

export function escapeHtml(value: string): string {
  return value
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

function pageTitle(data: Record<string, unknown>, slug: string): string {
  const title = data.title;
  return typeof title === 'string' && title.trim().length > 0 ? title : slug;
}

function pageDate(data: Record<string, unknown>): string | undefined {
  const date = data.date;
  return typeof date === 'string' && date.length > 0 ? date : undefined;
}

function pageTags(data: Record<string, unknown>): string[] | undefined {
  if (!Array.isArray(data.tags)) {
    return undefined;
  }
  const tags = data.tags.map(String).filter((tag) => tag.trim().length > 0);
  return tags.length > 0 ? tags : undefined;
}

function readPages(contentDir: string): Page[] {
  const entries = fs.readdirSync(contentDir);
  const files = entries.filter((entry) => MARKDOWN_EXTENSIONS.test(entry)).sort();
  const pages: Page[] = [];
  for (const file of files) {
    const raw = fs.readFileSync(path.join(contentDir, file), 'utf8');
    const slug = file.replace(MARKDOWN_EXTENSIONS, '');
    const { data, content, html } = renderMarkdownToHtml(raw);
    pages.push({
      slug,
      title: pageTitle(data, slug),
      date: pageDate(data),
      tags: pageTags(data),
      contentHtml: html,
      content,
    });
  }
  return pages;
}

export function renderPage(page: Page): string {
  const date = page.date ? `<p class="date">${escapeHtml(page.date)}</p>` : '';
  const tags = page.tags
    ? `<ul class="tags">${page.tags
        .map((tag) => `<li>${escapeHtml(tag)}</li>`)
        .join('')}</ul>`
    : '';
  return [
    '<!DOCTYPE html>',
    '<html lang="en">',
    '<head>',
    '<meta charset="utf-8">',
    '<meta name="viewport" content="width=device-width, initial-scale=1">',
    `<title>${escapeHtml(page.title)}</title>`,
    '</head>',
    '<body>',
    '<header>',
    `<h1>${escapeHtml(page.title)}</h1>`,
    date,
    tags,
    '</header>',
    '<main>',
    page.contentHtml,
    '</main>',
    '</body>',
    '</html>',
    '',
  ].join('\n');
}

function sortPages(pages: Page[]): Page[] {
  return [...pages].sort((a, b) => {
    if (a.date && b.date) {
      return b.date.localeCompare(a.date);
    }
    if (a.date) return -1;
    if (b.date) return 1;
    return a.slug.localeCompare(b.slug);
  });
}

export function renderIndex(pages: Page[]): string {
  const items = sortPages(pages)
    .map((page) => {
      const date = page.date ? ` <span class="date">${escapeHtml(page.date)}</span>` : '';
      return `    <li><a href="${escapeHtml(page.slug)}.html">${escapeHtml(
        page.title
      )}</a>${date}</li>`;
    })
    .join('\n');
  return [
    '<!DOCTYPE html>',
    '<html lang="en">',
    '<head>',
    '<meta charset="utf-8">',
    '<meta name="viewport" content="width=device-width, initial-scale=1">',
    '<title>Index</title>',
    '</head>',
    '<body>',
    '<h1>Index</h1>',
    '<ul>',
    items,
    '</ul>',
    '</body>',
    '</html>',
    '',
  ].join('\n');
}

/**
 * Build the site: every markdown file in `contentDir` becomes a page in
 * `outputDir` and an `index.html` listing all pages is generated.
 * Returns the list of generated pages.
 */
export function buildSite(options: BuildOptions): Page[] {
  const contentDir = path.resolve(options.contentDir);
  const outputDir = path.resolve(options.outputDir);

  if (!fs.existsSync(contentDir)) {
    throw new Error(`Content directory does not exist: ${contentDir}`);
  }
  if (!fs.statSync(contentDir).isDirectory()) {
    throw new Error(`Content path is not a directory: ${contentDir}`);
  }

  fs.mkdirSync(outputDir, { recursive: true });

  const pages = readPages(contentDir);
  for (const page of pages) {
    fs.writeFileSync(path.join(outputDir, `${page.slug}.html`), renderPage(page));
  }
  fs.writeFileSync(path.join(outputDir, 'index.html'), renderIndex(pages));
  return pages;
}

#!/usr/bin/env node
import { buildSite } from './generator';

const DEFAULT_CONTENT_DIR = './content';
const DEFAULT_OUTPUT_DIR = './dist';

export interface CliOptions {
  command: string;
  contentDir: string;
  outputDir: string;
}

export function parseArgs(argv: string[]): CliOptions {
  const opts: CliOptions = {
    command: '',
    contentDir: DEFAULT_CONTENT_DIR,
    outputDir: DEFAULT_OUTPUT_DIR,
  };
  const args = argv.slice();
  if (args.length === 0) {
    return opts;
  }
  opts.command = args.shift() ?? '';
  for (let i = 0; i < args.length; i++) {
    const arg = args[i];
    if (arg === '--content') {
      opts.contentDir = args[i + 1] ?? DEFAULT_CONTENT_DIR;
      i += 1;
    } else if (arg === '--output') {
      opts.outputDir = args[i + 1] ?? DEFAULT_OUTPUT_DIR;
      i += 1;
    } else if (arg === '--help' || arg === '-h') {
      opts.command = 'help';
    }
  }
  return opts;
}

export function printHelp(): void {
  console.log(
    [
      'Static Site Generator',
      '',
      'Usage:',
      '  npx ssg build [options]',
      '',
      'Options:',
      '  --content <dir>   Markdown content directory (default: ./content)',
      '  --output <dir>    Output directory (default: ./dist)',
      '  -h, --help        Show this help',
      '',
    ].join('\n')
  );
}

export function main(argv: string[]): number {
  const opts = parseArgs(argv);

  if (opts.command === 'help') {
    printHelp();
    return 0;
  }
  if (opts.command !== 'build') {
    console.error(`Unknown command: "${opts.command}". Run "npx ssg build".`);
    return 1;
  }

  try {
    const pages = buildSite({ contentDir: opts.contentDir, outputDir: opts.outputDir });
    console.log(`Built ${pages.length} page${pages.length === 1 ? '' : 's'} into ${opts.outputDir}`);
    return 0;
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    console.error(`Build failed: ${message}`);
    return 1;
  }
}

if (require.main === module) {
  process.exitCode = main(process.argv.slice(2));
}

import { parseFrontmatter, parseYamlBlock } from '../src/frontmatter';

describe('parseYamlBlock', () => {
  it('parses simple key: value pairs', () => {
    const result = parseYamlBlock('title: Hello\nsubtitle: A story\n');
    expect(result).toEqual({ title: 'Hello', subtitle: 'A story' });
  });

  it('parses quoted values and strips the quotes', () => {
    const result = parseYamlBlock('title: "Hello: World"\nsubtitle: \'Quoted\'\n');
    expect(result).toEqual({ title: 'Hello: World', subtitle: 'Quoted' });
  });

  it('parses booleans and numbers', () => {
    const result = parseYamlBlock('published: true\nfeatured: false\ncount: 42\n');
    expect(result).toEqual({ published: true, featured: false, count: 42 });
  });

  it('parses inline flow-style lists', () => {
    const result = parseYamlBlock('tags: [one, "two", three]\n');
    expect(result).toEqual({ tags: ['one', 'two', 'three'] });
  });

  it('ignores comments and blank lines', () => {
    const result = parseYamlBlock('# a comment\n\n title: X\n');
    expect(result).toEqual({ title: 'X' });
  });

  it('returns an empty object for an empty block', () => {
    expect(parseYamlBlock('')).toEqual({});
  });
});

describe('parseFrontmatter', () => {
  it('parses YAML frontmatter and strips it from the content', () => {
    const markdown = [
      '---',
      'title: My Page',
      'date: 2024-05-01',
      'tags: [a, b]',
      '---',
      '',
      '# Heading',
      '',
      'Body text.',
      '',
    ].join('\n');
    const { data, content } = parseFrontmatter(markdown);
    expect(data.title).toBe('My Page');
    expect(data.date).toBe('2024-05-01');
    expect(data.tags).toEqual(['a', 'b']);
    expect(content).toContain('# Heading');
    expect(content).toContain('Body text.');
    expect(content).not.toContain('title:');
  });

  it('handles markdown with no frontmatter', () => {
    const markdown = '# Just content\n';
    const { data, content } = parseFrontmatter(markdown);
    expect(data).toEqual({});
    expect(content).toBe(markdown);
  });

  it('merges YAML data on top of gray-matter output', () => {
    const markdown = ['---', 'title: YAML Title', 'tags: [x]', '---', '', 'Body'].join('\n');
    const { data } = parseFrontmatter(markdown);
    expect(data.title).toBe('YAML Title');
    expect(data.tags).toEqual(['x']);
  });

  it('parses JSON frontmatter via gray-matter', () => {
    const markdown = ['---json', '{"title": "JSON Title", "date": "2024-01-01"}', '---', '', 'Body'].join(
      '\n'
    );
    const { data, content } = parseFrontmatter(markdown);
    expect(data.title).toBe('JSON Title');
    expect(data.date).toBe('2024-01-01');
    expect(content).toContain('Body');
  });

  it('does not treat a lone --- paragraph as frontmatter', () => {
    const markdown = '---\n\nJust a horizontal rule.';
    const { data, content } = parseFrontmatter(markdown);
    expect(data).toEqual({});
    expect(content).toBe(markdown);
  });

  it('handles a BOM at the start of the file', () => {
    const markdown = ['\uFEFF---', 'title: Bom', '---', '', 'Body'].join('\n');
    const { data, content } = parseFrontmatter(markdown);
    expect(data.title).toBe('Bom');
    expect(content).toContain('Body');
  });
});

import { renderMarkdownToHtml } from '../src/markdown';

describe('renderMarkdownToHtml', () => {
  it('renders markdown to HTML', () => {
    const { html } = renderMarkdownToHtml('# Hello\n\nThis is **bold** text.');
    expect(html).toContain('<h1>Hello</h1>');
    expect(html).toContain('<strong>bold</strong>');
  });

  it('renders lists and links', () => {
    const { html } = renderMarkdownToHtml('- one\n- two\n\n[site](https://example.com)');
    expect(html).toContain('<ul>');
    expect(html).toContain('<li>one</li>');
    expect(html).toContain('<a href="https://example.com">site</a>');
  });

  it('extracts frontmatter data without rendering it', () => {
    const markdown = ['---', 'title: Data Title', 'tags: [t1]', '---', '', '## Section'].join('\n');
    const { html, data } = renderMarkdownToHtml(markdown);
    expect(data.title).toBe('Data Title');
    expect(data.tags).toEqual(['t1']);
    expect(html).toContain('<h2>Section</h2>');
    expect(html).not.toContain('Data Title');
  });

  it('handles empty content', () => {
    const { html } = renderMarkdownToHtml('');
    expect(html).toBe('');
  });
});

import fs from 'fs';
import os from 'os';
import path from 'path';
import { buildSite, renderIndex, renderPage } from '../src/generator';
import type { Page } from '../src/types';

function makeTempDir(prefix: string): string {
  return fs.mkdtempSync(path.join(os.tmpdir(), prefix));
}

function writeContent(dir: string, files: Record<string, string>): void {
  fs.mkdirSync(dir, { recursive: true });
  for (const [name, content] of Object.entries(files)) {
    fs.writeFileSync(path.join(dir, name), content);
  }
}

describe('renderPage', () => {
  it('renders a full HTML page with title and content', () => {
    const page: Page = {
      slug: 'hello',
      title: 'Hello',
      date: '2024-01-01',
      tags: ['intro'],
      contentHtml: '<p>World</p>',
      content: '# Hello',
    };
    const html = renderPage(page);
    expect(html).toContain('<!DOCTYPE html>');
    expect(html).toContain('<title>Hello</title>');
    expect(html).toContain('<h1>Hello</h1>');
    expect(html).toContain('<p>World</p>');
    expect(html).toContain('2024-01-01');
    expect(html).toContain('<li>intro</li>');
  });

  it('escapes special characters in metadata', () => {
    const page: Page = {
      slug: 'x',
      title: '<script>alert("x")</script>',
      contentHtml: '',
      content: '',
    };
    const html = renderPage(page);
    expect(html).toContain('&lt;script&gt;');
    expect(html).not.toContain('<script>');
  });
});

describe('renderIndex', () => {
  it('lists all pages as links to their html files', () => {
    const pages: Page[] = [
      { slug: 'a', title: 'Page A', contentHtml: '', content: '' },
      { slug: 'b', title: 'Page B', date: '2024-02-02', contentHtml: '', content: '' },
    ];
    const html = renderIndex(pages);
    expect(html).toContain('<a href="a.html">Page A</a>');
    expect(html).toContain('<a href="b.html">Page B</a>');
    expect(html).toContain('2024-02-02');
  });
});

describe('buildSite', () => {
  it('throws when the content directory does not exist', () => {
    const tmp = makeTempDir('ssg-missing-');
    expect(() =>
      buildSite({ contentDir: path.join(tmp, 'nope'), outputDir: path.join(tmp, 'dist') })
    ).toThrow(/Content directory does not exist/);
  });

  it('generates a page per markdown file plus an index', () => {
    const tmp = makeTempDir('ssg-build-');
    const contentDir = path.join(tmp, 'content');
    const outputDir = path.join(tmp, 'dist');
    writeContent(contentDir, {
      'first.md': '---\ntitle: First\ndate: 2024-03-01\ntags: [news]\n---\n\n# First post\n\nSome *body*.',
      'second.md': '# Second post\n\nPlain markdown.',
      'ignored.txt': 'not markdown',
    });

    const pages = buildSite({ contentDir, outputDir });

    expect(fs.existsSync(path.join(outputDir, 'first.html'))).toBe(true);
    expect(fs.existsSync(path.join(outputDir, 'second.html'))).toBe(true);
    expect(fs.existsSync(path.join(outputDir, 'ignored.html'))).toBe(false);
    expect(fs.existsSync(path.join(outputDir, 'index.html'))).toBe(true);

    const first = fs.readFileSync(path.join(outputDir, 'first.html'), 'utf8');
    expect(first).toContain('<title>First</title>');
